selector_to_html = {"a[href=\"#module-pyskyfire.viz.plot_ducts\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.viz.plot_ducts<a class=\"headerlink\" href=\"#module-pyskyfire.viz.plot_ducts\" title=\"Link to this heading\">\u00b6</a></h1><p>Pressure along a solved duct, against arc length.</p>", "a[href=\"PlotPipePressure.html#pyskyfire.viz.plot_ducts.PlotPipePressure\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.plot_ducts.PlotPipePressure\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.plot_ducts.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PlotPipePressure</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">*</span></span><span class=\"n\"><span class=\"pre\">results</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">labels</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">static</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">stagnation</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">markers</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">template</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'plotly_white'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../core/PlotBase.html#pyskyfire.viz.core.PlotBase\" title=\"pyskyfire.viz.core.PlotBase\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.viz.core.PlotBase</span></code></a></p><p>Static and/or stagnation pressure against arc length for solved pipes.</p><p>Each input is a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">DuctResult</span></code>, or any result with\nthe same <code class=\"docutils literal notranslate\"><span class=\"pre\">s</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">p_stagnation</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">p_static</span></code> station arrays. Markers\nsit on the <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PathStation</span></code> positions the solver\nevaluated; between them the line is only a straight join, so a lumped\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">RoundedBend</span></code> shows as one step across its arc.</p></dd>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"PlotPipePressureLoss.html#pyskyfire.viz.plot_ducts.PlotPipePressureLoss\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.viz.plot_ducts.PlotPipePressureLoss\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.viz.plot_ducts.</span></span><span class=\"sig-name descname\"><span class=\"pre\">PlotPipePressureLoss</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"o\"><span class=\"pre\">*</span></span><span class=\"n\"><span class=\"pre\">results</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">labels</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">None</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">markers</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">True</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">template</span></span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"default_value\"><span class=\"pre\">'plotly_white'</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../core/PlotBase.html#pyskyfire.viz.core.PlotBase\" title=\"pyskyfire.viz.core.PlotBase\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.viz.core.PlotBase</span></code></a></p><p>Cumulative irreversible pressure loss against arc length for solved pipes.</p><p>The loss at each station is the inlet stagnation pressure less the\nstagnation pressure there, so every curve starts at zero and ends at the\nresult\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">total_pressure_loss</span></code>. Inputs are as for\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PlotPipePressure</span></code>.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
